        with_chat_provider(&contents, provider).map_err(|source| ConfigWriteError::Parse {
            path: path.to_path_buf(),
            source,
        })?;
    if let Some(dir) = path.parent() {
        fs::create_dir_all(dir).map_err(io)?;
    }
    fs::write(path, updated).map_err(io)
